#!/bin/zsh
# 第四部分 Seedance。用法: seed_part4.sh s1|s2 [--yes]（不加 --yes 只出计划，不花钱）
# s1 唱跳（背影，传音频）：音频 123.20–129.20，按「裁掉开头约 0.94s」换算，片段 0s ≈ 歌曲 124.14
#    → P 125.40 = 1.26s / doom 125.58 = 1.44s / Loom 127.44 = 3.3s / masked 128.14 = 4.0s
# s2 谢幕（非唱跳，不传音频）：动作时间在代码里按 151.00 / 151.52 / 151.86 / 152.26 四声 oh 变速对齐
cd "${0:A:h}/.."   # 项目根（脚本所在 scripts/ 的上一级）
K=素材/关键帧; A=素材/音频
TAIL="Use @图像1 as the first frame. Lip sync strictly to @音频1: keep the original vocals, lyrics and timing exactly, do not re-sing or change the song."
C=(xk-video --model 2.0-fast --res 480p --ratio 16:9 --duration 6)
case $1 in
# I'm upping my P(doom), just as foretold by Loom, from masked…（背对镜头，面向看不见的观众）
s1) $C --ref $K/p4_s1_背影全身.png --audio $A/p4s1_123.20-129.20.mp3 --out 镜头/shot_p4s1_back480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, costume and character. Full-body shot from BEHIND, the whole figure always in frame from head to boots, she keeps her back to the camera almost the whole time, performing to a huge unseen audience in front of her, energetic 1990s idol dance synced to the beat, singing. Limited animation: strong clear held poses that snap from one to the next on the beat. Locked camera, single shot, no cuts. 0–1.2s: fist held high, swaying her hips to the beat, hair swinging. 1.26s, on \"P\": she jumps up. 1.44s, on \"doom\": she lands in a wide stance and throws both arms out wide to the audience. 2.0s: she sweeps one arm slowly from left to right across the whole audience. 2.6s: a big hair flip. 3.3s, on \"Loom\": she points far out into the distance. 4.0s: she looks back over her shoulder at the camera with a confident grin, just for a moment. 4.6–6s: she turns back to the audience, stomps on the beat and throws both arms up in a V. $TAIL";;
# 谢幕：挥手 → 两手向两侧伸出（像牵着旁边的人）→ 深鞠躬 → 抬头、含泪笑、眨眼
s2) $C --ref $K/p4_s2_谢幕全身.png --out 镜头/shot_p4s2_bow480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, costume and character. Full-body shot, the whole figure always in frame from head to boots, the final curtain call of her last concert. Limited animation like a 1990s anime: clear held poses, gentle movement. Locked camera, single shot, no cuts. 0–1.2s: she waves both raised hands wide from side to side, beaming. 1.2–2.0s: she lowers her arms and stretches them out to both sides at waist height, as if holding hands with friends standing next to her. 2.0–3.5s: she takes a deep, slow bow from the waist, her long hair falling forward over her shoulders, and holds it. 3.5–4.6s: she rises back up slowly, happy tears shining in her eyes, the brightest smile. 4.6–6s: she gives the viewer a small wink and a tiny wave with one hand near her face. Use @图像1 as the first frame.";;
# 10-19 v2：散发首帧 + 舞台服设定图当 @图像2（脸参考），已跑（2.25 元，seed 65849）；成片里水平镜像成 _v2_flip 用
s1v2) $C --ref $K/p4_s1_背影全身_v2.png --ref 素材/角色/设定图_舞台服_v1.png --audio $A/p4s1_123.20-129.20.mp3 --out 镜头/shot_p4s1_back480_v2.mp4 ${@:2} "2D retro anime, exactly matching the style, costume and character of @图像1. @图像2 is her character sheet: whenever any part of her face shows, it must be exactly the face of the girl in @图像2 (same big orange eyes, same bangs, same face shape). Her long wavy hair is always completely loose and down, never tied. Full-body shot from BEHIND, the whole figure always in frame from head to boots, she keeps her back to the camera the whole time, performing to a huge unseen audience in front of her, energetic 1990s idol dance synced to the beat, singing. Limited animation: strong clear held poses that snap from one to the next on the beat. Locked camera, single shot, no cuts. 0–1.2s: fist held high, swaying her hips to the beat, hair swinging. 1.26s, on \"P\": she jumps up. 1.44s, on \"doom\": she lands in a wide stance and throws both arms out wide to the audience. 2.0s: she sweeps one arm slowly from left to right across the whole audience. 2.6s: a big hair flip. 3.3s, on \"Loom\": she points far out into the distance, still facing away. 4.0s: her body stays facing the audience, ONLY her head turns to glance back over her shoulder at the camera with a confident grin, for about half a second, then she turns her head back. 4.6–6s: she stomps on the beat and throws both arms up in a V, back to the camera. $TAIL";;
esac
